using System;
using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace ProjectSpark.AAAArchitecture
{
    // Presentation only. Shared sprites and materials are generated by the editor.
    public static class SparkCinematicSkin
    {
        public const string ResourceRoot = "SparkCinematicUI/";
        public static readonly Color Cyan = new Color32(78, 222, 249, 255);
        public static readonly Color Gold = new Color32(255, 196, 82, 255);
        public static readonly Color Ink = new Color32(235, 247, 252, 255);
        public static readonly Color Muted = new Color32(150, 184, 201, 255);
        public static readonly Color Neutral = new Color32(66, 122, 145, 255);
        private static readonly Dictionary<string, Sprite> cache = new Dictionary<string, Sprite>();
        private static readonly Dictionary<string, Material> materials = new Dictionary<string, Material>();
        public const string MaterialRoot = "SparkCinematicUI/Materials/";
        public static readonly string[] ShaderRoles = { "Backdrop", "Panel", "Well", "Card", "Frame", "Button", "Primary", "Badge", "Hero" };
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void ResetCache() => ClearCache();
        public static void ClearCache() { cache.Clear(); materials.Clear(); }
        private static void ApplyMaterial(Image image, string name)
        {
            Material material = null;
            if (Array.IndexOf(ShaderRoles, name) >= 0)
            {
                if (!materials.TryGetValue(name, out material) || !material)
                {
                    material = Resources.Load<Material>(MaterialRoot + name);
                    if (material) materials[name] = material;
                }
            }
            if (!material || !material.shader || !material.shader.isSupported || !image.sprite)
            {
                // Keep the original sliced-sprite fallback if shaders are unavailable.
                image.material = null;
                if (image.TryGetComponent<SparkCinematicUV>(out var inactiveUV)) inactiveUV.enabled = false;
                return;
            }
            if (!image.TryGetComponent<SparkCinematicUV>(out var uv))
                uv = image.gameObject.AddComponent<SparkCinematicUV>();
            uv.enabled = true;
            if (image.material != material) image.material = material;
        }
        public static Sprite Get(string name)
        {
            if (!cache.TryGetValue(name, out Sprite value) || !value)
            {
                value = Resources.Load<Sprite>(ResourceRoot + name);
                if (value) cache[name] = value;
            }
            return value;
        }
        public static void Apply(Image image, string name, Color color, bool sliced = true)
        {
            if (!image) return;
            Sprite sprite = Get(name);
            image.sprite = sprite;
            image.type = sprite && sliced && sprite.border.sqrMagnitude > 0 ? Image.Type.Sliced : Image.Type.Simple;
            image.color = color;
            image.pixelsPerUnitMultiplier = name == "Button" || name == "Primary" || name == "Badge" ? 2f : 1f;
            ApplyMaterial(image, name);
        }
        public static RectTransform Rect(string name, Transform parent, Vector2 min, Vector2 max, Vector2 lo, Vector2 hi)
        {
            var rect = (RectTransform)new GameObject(name, typeof(RectTransform)).transform;
            rect.SetParent(parent, false);
            rect.gameObject.layer = parent.gameObject.layer;
            rect.anchorMin = min; rect.anchorMax = max; rect.offsetMin = lo; rect.offsetMax = hi;
            return rect;
        }
        public static Image Layer(string name, RectTransform parent, string sprite, Color color, bool behind = false, float inset = 0)
        {
            var rect = Rect(name, parent, Vector2.zero, Vector2.one, Vector2.one * inset, -Vector2.one * inset);
            rect.gameObject.AddComponent<LayoutElement>().ignoreLayout = true;
            var image = rect.gameObject.AddComponent<Image>(); image.raycastTarget = false;
            if (Get(sprite)) Apply(image, sprite, color);
            else image.color = Color.clear;
            if (behind) rect.SetAsFirstSibling();
            return image;
        }
        public static Image Frame(RectTransform parent, Color color, string name = "Cinematic Frame", float inset = 0)
        { return Layer(name, parent, "Frame", color, false, inset); }
        public static void Plate(Image image, string name = "Panel")
        {
            if (Get(name)) Apply(image, name, Color.white);
        }
        public static Image PlateLayer(RectTransform parent, string name, string sprite = "Panel", float inset = 0)
        { return Layer(name, parent, sprite, Color.white, true, inset); }
        public static void StyleButton(Button button, bool primary = false)
        {
            if (!button || !button.image) return;
            var sprite = Get(primary ? "Primary" : "Button");
            if (!sprite) return;
            Apply(button.image, primary ? "Primary" : "Button", Color.white);
            button.transition = Selectable.Transition.ColorTint;
            var colors = button.colors;
            colors.normalColor = Color.white;
            colors.highlightedColor = new Color(1f, 1f, 1f, 1f);
            colors.selectedColor = new Color(.85f, 1f, 1f, 1f);
            colors.pressedColor = new Color(.72f, .8f, .86f, 1f);
            colors.disabledColor = new Color(.53f, .57f, .62f, .85f);
            colors.colorMultiplier = 1.1f; colors.fadeDuration = .14f;
            button.colors = colors;
        }
        public static void StyleText(TMP_Text text, bool heading = false)
        {
            if (!text) return;
            text.extraPadding = true;
            text.richText = false;
            if (heading) { text.fontStyle = FontStyles.Bold; text.characterSpacing = .35f; }
        }
        // Only for the generated standalone presentation. The actual campaign is styled at its explicit construction points.
        public static void StyleGeneratedPresentation(GameObject root)
        {
            if (!root) return;
            foreach (var image in root.GetComponentsInChildren<Image>(true))
            {
                if (image.GetComponentInParent<SparkAAALevelCard>()) continue;
                if (image.sprite) continue;
                switch (image.name)
                {
                    case "SparkLevelSelectionPanel": Plate(image, "Backdrop"); break;
                    case "DivisionSidebar": case "MissionDetail": Plate(image); break;
                    case "LevelScroll": case "DivisionScroll": case "DetailScroll": Plate(image, "Well"); break;
                }
            }
            foreach (var button in root.GetComponentsInChildren<Button>(true))
                if (!button.GetComponentInParent<SparkAAALevelCard>()) StyleButton(button, button.name == "Action" || button.name == "Launch");
        }
    }
}
